# Clean, typed, documented Python
def calculate_discount(price: float, rate: float = 0.10) -> float:
    """Return price after applying discount percentage."""
    assert 0 <= rate <= 1, "Rate must be between 0 and 1"
    return round(price * (1 - rate), 2)

print("Final price:", calculate_discount(50.0))

# Bad (deep nesting) vs Good (guard clauses)
def get_ticket_price(age: int) -> int:
    if age < 0:
        return 0  # Guard clause
    if age < 12:
        return 8
    if age >= 65:
        return 10
    return 15

print("Senior price:", get_ticket_price(65))

