def is_valid_username(name: str) -> bool:
    return len(name) >= 4 and name.isalnum()
assert is_valid_username('alex99') is True
print(is_valid_username('alex99'))

def apply_tax(subtotal: float, rate: float = 0.05) -> float:
    """Calculate total with tax rounded to 2 decimals."""
    assert subtotal >= 0 and rate >= 0, 'Values must be non-negative'
    return round(subtotal * (1 + rate), 2)
assert apply_tax(100.0, 0.08) == 108.0
print(f"Total: ${apply_tax(100.0, 0.08):.2f}")
